tokens.getLastSeen = async (ids) => {
	if (!Array.isArray(ids)) {
		throw new Error('[[error:invalid-data]]');
	}
	if (!ids.length) {
		return [];
	}
	const scores = await db.sortedSetScores('tokens:lastSeen', ids);
	return scores.map(score => (
		score === null || score === undefined || !Number.isFinite(Number(score)) ? null : Number(score)
	));
};

tokens.get = async (ids) => {
	if (typeof ids !== 'string' && (!Array.isArray(ids) || ids.some(id => typeof id !== 'string'))) {
		throw new Error('[[error:invalid-data]]');
	}
	const single = typeof ids === 'string';
	const tokenIds = single ? [ids] : ids;
	if (!tokenIds.length) {
		return [];
	}
	const [data, lastSeen] = await Promise.all([
		db.getObjects(tokenIds.map(token => `token:${token}`)),
		tokens.getLastSeen(tokenIds),
	]);
	const result = data.map((item, index) => (item ? {
		uid: Number(item.uid),
		description: item.description === undefined ? '' : item.description,
		timestamp: Number(item.timestamp),
		lastSeen: lastSeen[index],
	} : null));
	return single ? result[0] : result;
};

